 "content": "def transform(grid):
    """Move the non-background object next to the 2-line and mark its far edge in 8."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = 4
    # Locate a full-length straight 2-line.
    line = None
    for r in range(h):
        if all(g[r][c] == 2 for c in range(w)):
            line = ('h', r)
            break
    if line is None:
        for c in range(w):
            if all(g[r][c] == 2 for r in range(h)):
                line = ('v', c)
                break
    if line is None:
        return g
    axis, pos = line
    points = [(r, c, g[r][c]) for r in range(h) for c in range(w)
              if g[r][c] not in (bg, 2)]
    if not points:
        return g
    if axis == 'h':
        min_r = min(r for r, _, _ in points)
        max_r = max(r for r, _, _ in points)
        if max_r < pos:
            shift = pos - 1 - max_r
            mark = min_r + shift - 1
        else:
            shift = pos + 1 - min_r
            mark = max_r + shift + 1
        for r, c, _ in points:
            g[r][c] = bg
        for r, c, color in points:
            g[r + shift][c] = color
        if 0 <= mark < h:
            g[mark] = [8] * w
    else:
        min_c = min(c for _, c, _ in points)
        max_c = max(c for _, c, _ in points)
        if max_c < pos:
            shift = pos - 1 - max_c
            mark = min_c + shift - 1
        else:
            shift = pos + 1 - min_c
            mark = max_c + shift + 1
        for r, c, _ in points:
            g[r][c] = bg
        for r, c, color in points:
            g[r][c + shift] = color
        if 0 <= mark < w:
            for r in range(h):
                g[r][mark] = 8
    return g

